import { app, BrowserWindow, globalShortcut, screen, ipcMain } from 'electron';
import { autoUpdater } from 'electron-updater';
import path from 'node:path';

let mainWindow: BrowserWindow | null = null;
let cursorInterval: NodeJS.Timeout | null = null;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 400,
    height: 600,
    transparent: true,
    frame: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    resizable: false,
    hasShadow: false,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'preload.js'),
    },
  });

  mainWindow.setAlwaysOnTop(true, 'screen-saver', 1);
  mainWindow.setIgnoreMouseEvents(true, { forward: true });

  if (process.env.NODE_ENV === 'development') {
    mainWindow.loadURL('http://localhost:5173');
    mainWindow.webContents.openDevTools({ mode: 'detach' });
  } else {
    mainWindow.loadFile(path.join(__dirname, '../dist/index.html'));
  }

  const primaryDisplay = screen.getPrimaryDisplay();
  const { width, height } = primaryDisplay.workArea;
  mainWindow.setPosition(20, height - 620);

  startCursorTracking();

  globalShortcut.register('CommandOrControl+I', () => {
    mainWindow?.webContents.send('toggle-voice');
  });

  autoUpdater.checkForUpdatesAndNotify();
  setInterval(() => {
    autoUpdater.checkForUpdatesAndNotify();
  }, 4 * 60 * 60 * 1000);
}

function startCursorTracking() {
  cursorInterval = setInterval(() => {
    if (!mainWindow) return;

    const point = screen.getCursorScreenPoint();
    const display = screen.getDisplayNearestPoint(point);
    if (!display) return;

    const { x, y, width, height } = display.workArea;
    const targetX = x + 20;
    const targetY = y + height - 620;

    const clampedX = Math.max(x, Math.min(x + width - 400, targetX));
    const clampedY = Math.max(y, Math.min(y + height - 600, targetY));

    mainWindow.setPosition(clampedX, clampedY);
  }, 16);
}

app.whenReady().then(createWindow);

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

app.on('activate', () => {
  if (BrowserWindow.getAllWindows().length === 0) createWindow();
});

app.on('will-quit', () => {
  if (cursorInterval) clearInterval(cursorInterval);
  globalShortcut.unregisterAll();
});

screen.on('display-removed', () => {
  const primaryDisplay = screen.getPrimaryDisplay();
  const { width, height } = primaryDisplay.workArea;
  mainWindow?.setPosition(20, height - 620);
});

ipcMain.on('app-quit', () => {
  app.quit();
});
```

