import { create } from 'zustand';

interface VoiceState {
  wsConnected: boolean;
  micActive: boolean;
  voiceEnabled: boolean;
  isSending: boolean;
  isThinking: boolean;
  isSpeaking: boolean;
  userText: string;
  irisText: string;
  speakingVolume: number;

  toggleVoice: () => void;
  setStatus: (status: Partial<VoiceState>) => void;
  updateTranscript: (speaker: 'user' | 'iris', text: string) => void;
  clearTranscripts: () => void;
}

export const useVoiceStore = create<VoiceState>((set) => ({
  wsConnected: false,
  micActive: false,
  voiceEnabled: false,
  isSending: false,
  isThinking: false,
  isSpeaking: false,
  userText: '',
  irisText: '',
  speakingVolume: 0,

  toggleVoice: () =>
    set((state) => {
      const enabled = !state.voiceEnabled;
      if (enabled) {
        (window as any)._voicePipeline?.start();
      } else {
        (window as any)._voicePipeline?.stop();
      }
      return { voiceEnabled: enabled };
    }),

  setStatus: (status) => set(status),

  updateTranscript: (speaker, text) =>
    set({
      [speaker === 'user' ? 'userText' : 'irisText']: text,
    }),

  clearTranscripts: () => set({ userText: '', irisText: '' }),
}));
