import { useVoiceStore } from '../stores/voiceStore';

export class VoicePipeline {
  private ws: WebSocket | null = null;
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private mediaStream: MediaStream | null = null;
  private scriptProcessor: ScriptProcessorNode | null = null;
  private speakingVolume = 0;
  private audioQueue: AudioBuffer[] = [];
  private isPlayingAudio = false;
  private reconnectAttempts = 0;

  async start() {
    console.log('[VoicePipeline] Starting...');

    const geminiApiKey = import.meta.env.VITE_GEMINI_API_KEY;
    if (!geminiApiKey) {
      console.error('[VoicePipeline] VITE_GEMINI_API_KEY not set');
      alert('Please set VITE_GEMINI_API_KEY in .env file');
      return;
    }

    const wsUrl = `wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContent?key=${geminiApiKey}`;
    this.ws = new WebSocket(wsUrl);

    this.ws.onopen = () => {
      console.log('[VoicePipeline] WebSocket connected');
      useVoiceStore.getState().setStatus({ wsConnected: true });
      this.reconnectAttempts = 0;

      this.ws?.send(
        JSON.stringify({
          setup: {
            model: 'models/gemini-2.0-flash-exp',
            generation_config: { response_modalities: ['AUDIO'] },
            system_instruction: {
              parts: [{ text: 'You are Iris, a friendly desktop companion. Keep responses concise (1-2 sentences).' }],
            },
          },
        })
      );
    };

    this.ws.onmessage = async (event) => {
      const data = JSON.parse(event.data);

      if (data.serverContent?.turnComplete) {
        console.log('[VoicePipeline] Turn complete');
        useVoiceStore.getState().setStatus({ isThinking: false, isSpeaking: false });
      }

      if (data.serverContent?.modelTurn?.parts) {
        for (const part of data.serverContent.modelTurn.parts) {
          if (part.text) {
            console.log('[VoicePipeline] Text:', part.text);
            useVoiceStore.getState().updateTranscript('iris', part.text);
          }

          if (part.inlineData?.mimeType === 'audio/pcm' && part.inlineData.data) {
            console.log('[VoicePipeline] Audio received');
            useVoiceStore.getState().setStatus({ isSpeaking: true });
            await this.playAudioChunk(part.inlineData.data);
          }
        }
      }
    };

    this.ws.onerror = (error) => {
      console.error('[VoicePipeline] WebSocket error:', error);
      useVoiceStore.getState().setStatus({ wsConnected: false });
    };

    this.ws.onclose = (event) => {
      console.warn(`[VoicePipeline] WebSocket closed (code: ${event.code})`);
      useVoiceStore.getState().setStatus({ wsConnected: false });

      if (event.code === 1008) {
        alert('Gemini API rate limit reached. Please try again later.');
        useVoiceStore.getState().setStatus({ voiceEnabled: false });
        return;
      }

      const delay = Math.min(3000 * Math.pow(2, this.reconnectAttempts), 30000);
      setTimeout(() => {
        if (useVoiceStore.getState().voiceEnabled) {
          console.log(`[VoicePipeline] Reconnecting (attempt ${this.reconnectAttempts + 1})...`);
          this.reconnectAttempts++;
          this.start();
        }
      }, delay);
    };

    try {
      this.mediaStream = await navigator.mediaDevices.getUserMedia({
        audio: { sampleRate: 16000, channelCount: 1, echoCancellation: true, noiseSuppression: true },
      });

      console.log('[VoicePipeline] Microphone active');
      useVoiceStore.getState().setStatus({ micActive: true });

      this.audioContext = new AudioContext({ sampleRate: 16000 });
      const source = this.audioContext.createMediaStreamSource(this.mediaStream);

      this.analyser = this.audioContext.createAnalyser();
      this.analyser.fftSize = 256;
      source.connect(this.analyser);

      this.scriptProcessor = this.audioContext.createScriptProcessor(4096, 1, 1);
      source.connect(this.scriptProcessor);
      this.scriptProcessor.connect(this.audioContext.destination);

      this.scriptProcessor.onaudioprocess = (e) => {
        if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;

        const inputData = e.inputBuffer.getChannelData(0);
        const pcm16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) {
          const s = Math.max(-1, Math.min(1, inputData[i]));
          pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
        }

        const base64 = btoa(String.fromCharCode(...new Uint8Array(pcm16.buffer)));
        this.ws.send(JSON.stringify({ realtimeInput: { mediaChunks: [{ data: base64, mimeType: 'audio/pcm' }] } }));

        useVoiceStore.getState().setStatus({ isSending: this.getIsSpeaking() });
      };

      this.startVolumeAnalysis();
    } catch (err) {
      console.error('[VoicePipeline] Microphone denied:', err);
      useVoiceStore.getState().setStatus({ micActive: false, voiceEnabled: false });
      alert('Microphone access required for voice features.');
    }
  }

  stop() {
    console.log('[VoicePipeline] Stopping...');
    this.ws?.close();
    this.audioContext?.close();
    this.mediaStream?.getTracks().forEach((track) => track.stop());
    this.scriptProcessor?.disconnect();
    useVoiceStore.getState().setStatus({ voiceEnabled: false, micActive: false, wsConnected: false, isSending: false });
  }

  getSpeakingVolume(): number {
    return this.speakingVolume;
  }

  private getIsSpeaking(): boolean {
    return this.speakingVolume > 0.1;
  }

  private startVolumeAnalysis() {
    if (!this.analyser) return;
    const dataArray = new Uint8Array(this.analyser.frequencyBinCount);

    const analyze = () => {
      if (!this.analyser) return;
      this.analyser.getByteFrequencyData(dataArray);
      const average = dataArray.reduce((sum, value) => sum + value, 0) / dataArray.length;
      this.speakingVolume = average / 255;
      requestAnimationFrame(analyze);
    };

    analyze();
  }

  private async playAudioChunk(base64Data: string) {
    if (!this.audioContext) return;

    try {
      const binaryString = atob(base64Data);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const pcm16 = new Int16Array(bytes.buffer);
      const float32 = new Float32Array(pcm16.length);
      for (let i = 0; i < pcm16.length; i++) {
        float32[i] = pcm16[i] / 32768.0;
      }

      const audioBuffer = this.audioContext.createBuffer(1, float32.length, 16000);
      audioBuffer.copyToChannel(float32, 0);

      this.audioQueue.push(audioBuffer);
      if (!this.isPlayingAudio) this.playNextInQueue();
    } catch (err) {
      console.error('[VoicePipeline] Audio decode failed:', err);
      if (this.audioQueue.length > 0) this.playNextInQueue();
    }
  }

  private playNextInQueue() {
    if (this.audioQueue.length === 0) {
      this.isPlayingAudio = false;
      useVoiceStore.getState().setStatus({ isSpeaking: false });
      return;
    }

    this.isPlayingAudio = true;
    const buffer = this.audioQueue.shift()!;
    const source = this.audioContext!.createBufferSource();
    source.buffer = buffer;
    source.connect(this.audioContext!.destination);
    source.onended = () => this.playNextInQueue();
    source.start();
  }
}

(window as any)._voicePipeline = new VoicePipeline();
```

