import type { VRM } from '@pixiv/three-vrm';

let time = 0;
let blinkTimer = 0;
const BLINK_INTERVAL_MIN = 4;
const BLINK_INTERVAL_MAX = 8;
let nextBlinkTime = randomBlink();

function randomBlink() {
  return BLINK_INTERVAL_MIN + Math.random() * (BLINK_INTERVAL_MAX - BLINK_INTERVAL_MIN);
}

export function applyProceduralOverlays(vrm: VRM, delta: number) {
  time += delta;
  blinkTimer += delta;

  // Head look-around (slow sine waves)
  if (vrm.humanoid) {
    const head = vrm.humanoid.getNormalizedBoneNode('head');
    if (head) {
      head.rotation.y = Math.sin(time * 0.3) * 0.26; // ±15°
      head.rotation.x = Math.sin(time * 0.2 + 0.5) * 0.17; // ±10°
      head.rotation.z = Math.sin(time * 0.25 + 1.0) * 0.09; // ±5°
    }
  }

  // Finger curl (relaxed pose)
  const fingers = [
    'leftIndexProximal',
    'leftMiddleProximal',
    'leftRingProximal',
    'leftLittleProximal',
    'rightIndexProximal',
    'rightMiddleProximal',
    'rightRingProximal',
    'rightLittleProximal',
  ];

  fingers.forEach((fingerName, i) => {
    const bone = vrm.humanoid?.getNormalizedBoneNode(fingerName as any);
    if (bone) {
      const baseCurl = -0.3;
      const wave = Math.sin(time * 0.5 + i * 0.3) * 0.1;
      bone.rotation.z = baseCurl + wave;
    }
  });

  // Blinking
  if (blinkTimer >= nextBlinkTime) {
    blinkTimer = 0;
    nextBlinkTime = randomBlink();
    triggerBlink(vrm);
  }

  // Lip-sync (driven by voice pipeline)
  const volume = (window as any)._voicePipeline?.getSpeakingVolume() || 0;

  if (vrm.expressionManager) {
    if (volume > 0.1) {
      vrm.expressionManager.setValue('aa', Math.min(volume * 2.0, 1.0));
      vrm.expressionManager.setValue('oh', Math.min(volume * 1.5, 1.0));
      vrm.expressionManager.setValue('happy', 0);
    } else {
      vrm.expressionManager.setValue('aa', 0);
      vrm.expressionManager.setValue('oh', 0);
      vrm.expressionManager.setValue('happy', 0.3);
    }
  }
}

function triggerBlink(vrm: VRM) {
  if (!vrm.expressionManager) return;
  vrm.expressionManager.setValue('blink', 1);
  setTimeout(() => {
    vrm.expressionManager?.setValue('blink', 0);
  }, 150);
}
