import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { VRMLoaderPlugin, VRMUtils, VRM } from '@pixiv/three-vrm';
import { applyProceduralOverlays } from '../utils/procedural-overlays';

export function AvatarCanvas() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const vrmRef = useRef<VRM | null>(null);
  const mixerRef = useRef<THREE.AnimationMixer | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(30, 400 / 600, 0.1, 20);
    camera.position.set(0, 1.4, 2.5);
    camera.lookAt(0, 1.3, 0);
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({
      canvas: canvasRef.current,
      alpha: true,
      antialias: true,
    });
    renderer.setSize(400, 600);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    rendererRef.current = renderer;

    const directionalLight = new THREE.DirectionalLight(0xffffff, Math.PI);
    directionalLight.position.set(1, 1, 1);
    scene.add(directionalLight);

    const ambientLight = new THREE.AmbientLight(0xffffff, Math.PI / 2);
    scene.add(ambientLight);

    const loader = new GLTFLoader();
    loader.register((parser) => new VRMLoaderPlugin(parser));

    console.log('[AvatarCanvas] Loading VRM model...');

    loader.load(
      '/avatar.glb',
      async (gltf) => {
        console.log('[AvatarCanvas] VRM loaded, optimizing...');
        const vrm = gltf.userData.vrm as VRM;

        VRMUtils.removeUnnecessaryVertices(gltf.scene);
        VRMUtils.removeUnnecessaryJoints(gltf.scene);

        try {
          await VRMUtils.combineSkeletons(gltf.scene);
          console.log('[AvatarCanvas] Skeletons combined');
        } catch (e) {
          console.warn('[AvatarCanvas] combineSkeletons failed (non-critical):', e);
        }

        vrm.scene.rotation.y = Math.PI;
        scene.add(vrm.scene);
        vrmRef.current = vrm;

        console.log('[AvatarCanvas] VRM added to scene');

        loader.load(
          '/idle_loop.vrma',
          (animGltf) => {
            const mixer = new THREE.AnimationMixer(vrm.scene);
            const clip = animGltf.animations[0];

            if (!clip) {
              console.error('[AvatarCanvas] No animation found');
              return;
            }

            const action = mixer.clipAction(clip);
            action.play();
            mixerRef.current = mixer;

            console.log('[AvatarCanvas] Idle animation playing');
          },
          undefined,
          (error) => {
            console.error('[AvatarCanvas] Failed to load animation:', error);
          }
        );
      },
      (progress) => {
        const percent = ((progress.loaded / progress.total) * 100).toFixed(1);
        console.log(`[AvatarCanvas] Loading: ${percent}%`);
      },
      (error) => {
        console.error('[AvatarCanvas] Failed to load VRM:', error);
        showErrorOverlay('Avatar failed to load. Please restart the app.');
      }
    );

    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const delta = clock.getDelta();

      if (mixerRef.current) {
        mixerRef.current.update(delta);
      }

      if (vrmRef.current) {
        applyProceduralOverlays(vrmRef.current, delta);
        vrmRef.current.update(delta);
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    }

    animate();

    return () => {
      renderer.dispose();
      scene.clear();
    };
  }, []);

  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full" />;
}

function showErrorOverlay(message: string) {
  const errorDiv = document.createElement('div');
  errorDiv.innerHTML = `
    <div class="text-red-500 text-center p-4">
      <p class="text-xl font-bold mb-2">Avatar Failed to Load</p>
      <p class="text-sm">Possible reasons:</p>
      <ul class="list-disc list-inside text-left mt-2 text-xs">
        <li>Missing or corrupted avatar.glb file</li>
        <li>Invalid VRM 1.0 model</li>
        <li>Network issue (if loading from CDN)</li>
      </ul>
      <button 
        onclick="location.reload()" 
        class="mt-4 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 cursor-pointer pointer-events-auto"
      >
        Restart App
      </button>
    </div>
  `;
  errorDiv.className = 'fixed inset-0 flex items-center justify-center bg-black/90 pointer-events-none';
  document.body.appendChild(errorDiv);
}
