import { useVoiceStore } from '../stores/voiceStore';
import { useEffect, useState } from 'react';

export function UIOverlay() {
  const {
    wsConnected,
    micActive,
    voiceEnabled,
    isSending,
    isThinking,
    isSpeaking,
    userText,
    irisText,
  } = useVoiceStore();

  return (
    <div className="fixed inset-0 pointer-events-none">
      <div className="absolute top-4 left-4 flex gap-2">
        <StatusDot label="WS" active={wsConnected} color="green" />
        <StatusDot label="MIC" active={micActive} color="green" />
        <StatusDot label="VOICE" active={voiceEnabled} color="blue" />
        <StatusDot label="SEND" active={isSending} color="yellow" pulse={isSending} />
        <StatusDot label="THINK" active={isThinking} color="purple" spin={isThinking} />
        <StatusDot label="SPEAK" active={isSpeaking} color="pink" bounce={isSpeaking} />
      </div>

      <SpeechBubble text={userText} speaker="user" />
      <SpeechBubble text={irisText} speaker="iris" />
    </div>
  );
}

interface StatusDotProps {
  label: string;
  active: boolean;
  color: 'green' | 'blue' | 'yellow' | 'purple' | 'pink';
  pulse?: boolean;
  spin?: boolean;
  bounce?: boolean;
}

function StatusDot({ label, active, color, pulse, spin, bounce }: StatusDotProps) {
  const colorClasses = {
    green: 'bg-green-500',
    blue: 'bg-blue-500',
    yellow: 'bg-yellow-500',
    purple: 'bg-purple-500',
    pink: 'bg-pink-500',
  };

  const animationClasses = [
    pulse && 'animate-pulse',
    spin && 'animate-spin',
    bounce && 'animate-bounce',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div className="flex items-center gap-1.5 bg-black/60 rounded-full px-2 py-1">
      <div
        className={`w-2 h-2 rounded-full ${active ? colorClasses[color] : 'bg-gray-500'} ${animationClasses}`}
      />
      <span className="text-xs text-white/80 font-mono">{label}</span>
    </div>
  );
}

interface SpeechBubbleProps {
  text: string;
  speaker: 'user' | 'iris';
}

function SpeechBubble({ text, speaker }: SpeechBubbleProps) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (text) {
      setVisible(true);
      const timer = setTimeout(() => {
        setVisible(false);
      }, 5000);
      return () => clearTimeout(timer);
    } else {
      setVisible(false);
    }
  }, [text]);

  if (!visible || !text) return null;

  const isUser = speaker === 'user';

  return (
    <div
      className={`absolute bottom-32 max-w-xs transition-opacity duration-300 ${
        isUser ? 'left-8' : 'right-8'
      } ${visible ? 'opacity-100' : 'opacity-0'}`}
    >
      <div
        className={`${
          isUser ? 'bg-blue-500/90' : 'bg-purple-500/90'
        } text-white p-3 rounded-lg shadow-lg`}
      >
        <p className="text-xs font-bold uppercase tracking-wide mb-1">
          {isUser ? 'You' : 'Iris'}
        </p>
        <p className="text-sm leading-relaxed">{text}</p>
      </div>
    </div>
  );
}
