import { useVoiceStore } from './stores/voiceStore';

export function App() {
  const toggleVoice = useVoiceStore((state) => state.toggleVoice);

  useEffect(() => {
    const handleToggle = () => {
      console.log('[App] Ctrl+I pressed, toggling voice');
      toggleVoice();
    };

    window.electron?.ipcRenderer?.on('toggle-voice', handleToggle);

    return () => {
      window.electron?.ipcRenderer?.removeListener('toggle-voice', handleToggle);
    };
  }, [toggleVoice]);

  return (
    <div className="w-full h-full">
      <AvatarCanvas />
      <UIOverlay />
    </div>
  );
}
